import { useIntl } from 'react-intl';

import {
  BigNumber,
  ChartHeader,
  DataStateHandler,
  SubPillarCard,
} from 'components';

import {
  RESOURCE_ALLOCATION_CARD_KEYS,
  type ResourceAllocationCardKey,
} from '../../../constants';
import type { ResourceAllocationCardsData } from '../../../types';
import { StyledResourceAllocationSection } from './ResourceAllocationSection.styles';

export interface ResourceAllocationSectionProps {
  isDesktopLarge: boolean;
  loading?: boolean;
  error?: unknown;
  resourceAllocationCardsData?: ResourceAllocationCardsData;
  onCardClick: (key: ResourceAllocationCardKey) => void;
}

export const ResourceAllocationSection = ({
  isDesktopLarge,
  loading,
  error,
  resourceAllocationCardsData,
  onCardClick,
}: ResourceAllocationSectionProps) => {
  const { formatMessage } = useIntl();

  return (
    <StyledResourceAllocationSection data-testid="resource-allocation-section">
      <SubPillarCard
        title={formatMessage({
          id: 'ConnectionsCreativity.Home.resourceAllocation.title',
        })}
        description={formatMessage({
          id: 'ConnectionsCreativity.Home.resourceAllocation.description',
        })}
      >
        {RESOURCE_ALLOCATION_CARD_KEYS.map((key) => {
          const cardData = resourceAllocationCardsData?.[key];

          return (
            <DataStateHandler
              key={key}
              loading={loading}
              error={error}
              empty={!resourceAllocationCardsData}
              skeletonProps={{
                height: '166px',
                width: '100%',
                length: 1,
              }}
            >
              <BigNumber
                header={
                  <ChartHeader
                    title={cardData?.title}
                    period={cardData?.period}
                    config={{
                      inline: 'horizontal',
                      type: 'small',
                    }}
                  />
                }
                data={cardData?.bigNumberData ?? []}
                asCard={true}
                size={isDesktopLarge ? 'medium' : 'small'}
                spacing="loose"
                onClick={() => onCardClick(key)}
                style={{ minHeight: '166px' }}
              />
            </DataStateHandler>
          );
        })}
      </SubPillarCard>
    </StyledResourceAllocationSection>
  );
};
